type Transform = (value: string) => string;

interface SlugStrategy {
  readonly name: string;
  apply(value: string): string;
}

class LowercaseStrategy implements SlugStrategy {
  readonly name = "lowercase";
  apply(value: string): string {
    return value.toLowerCase();
  }
}

class SeparatorStrategy implements SlugStrategy {
  readonly name = "separator";
  constructor(private readonly separator: string) {}
  apply(value: string): string {
    return value.replace(/[^\p{L}\p{N}]+/gu, this.separator);
  }
}

class TrimStrategy implements SlugStrategy {
  readonly name = "trim";
  apply(value: string): string {
    return value.replace(/^-+|-+$/gu, "");
  }
}

class SlugPipeline {
  private readonly strategies: SlugStrategy[] = [];
  register(strategy: SlugStrategy): this {
    this.strategies.push(strategy);
    return this;
  }
  run(value: string): string {
    return this.strategies.reduce((acc, s) => s.apply(acc), value);
  }
}

const registry = new SlugPipeline()
  .register(new LowercaseStrategy())
  .register(new SeparatorStrategy("-"))
  .register(new TrimStrategy());

export function slugify(input: string): string {
  return registry.run(input);
}
